/**
 * Builds storefront-friendly metadata without changing the source catalogue.
 * Values such as ISBN, author, page count and dimensions are never guessed.
 */
export type StoreProductMetadata = {
  tags: string[];
  searchKeywords: string[];
  metaTitle: string;
  metaDescription: string;
  availabilityStatus: NonNullable<Product["availabilityStatus"]>;
  catalogueStatus: NonNullable<Product["catalogueStatus"]>;
  discountPercentage: number;
  isDigital: boolean;
  isInStock: boolean;
  isLowStock: boolean;
};

export function getProductStoreMetadata(product: Product): StoreProductMetadata {
  const tags = [...new Set([
    ...(product.subjects ?? []),
    ...(product.topics ?? []),
    ...(product.tags ?? []),
    ...(product.category ? [product.category] : []),
    ...(product.series ? [product.series] : []),
    ...(product.language ? [product.language] : []),
    ...(product.productType ? [product.productType] : []),
  ].map((value) => value.trim()).filter(Boolean))];

  const searchKeywords = [...new Set([
    product.title,
    product.titleAr,
    product.subtitle,
    ...(product.authors ?? []),
    ...(product.authorsAr ?? []),
    product.publisher,
    product.isbn,
    product.isbn13,
    product.isbn10,
    product.barcode,
    product.sku,
    product.category,
    ...(product.subjects ?? []),
    ...(product.topics ?? []),
    ...(product.tags ?? []),
  ].filter((value): value is string => Boolean(value?.trim())))];

  const isInactive = product.active === false;
  const availabilityStatus = isInactive
    ? "inactive"
    : product.stock <= 0
      ? "out-of-stock"
      : product.stock <= 5
        ? "low-stock"
        : "in-stock";

  const isSample = product.description.includes("DEMO DATA") ||
    product.website?.toLowerCase().includes("demo") === true;

  const catalogueStatus = isSample
    ? "sample"
    : product.website === "UBH (OFFICIAL)"
      ? "official-source"
      : "needs-review";

  const discountPercentage = product.oldPrice && product.oldPrice > product.price
    ? Math.round(((product.oldPrice - product.price) / product.oldPrice) * 100)
    : 0;

  const cleanDescription = product.description
    .replace(/^DEMO DATA\s*[—-]\s*/i, "")
    .trim();

  return {
    tags,
    searchKeywords,
    metaTitle: product.metaTitle?.trim() || `${product.title} | University Book House`,
    metaDescription: product.metaDescription?.trim() ||
      (cleanDescription || `Explore ${product.title} by ${product.publisher} at University Book House.`)
        .slice(0, 160),
    availabilityStatus,
    catalogueStatus,
    discountPercentage,
    isDigital: product.productType === "ebook" || product.format?.toLowerCase().includes("ebook") === true,
    isInStock: !isInactive && product.stock > 0,
    isLowStock: !isInactive && product.stock > 0 && product.stock <= 5,
  };
}

/** Returns a product with derived storefront metadata for cards, filters and SEO. */
export function getStoreProduct(product: Product): Product & StoreProductMetadata {
  return { ...product, ...getProductStoreMetadata(product) };
}

/** Use this when preparing a collection for storefront display. */
export function getStoreProducts(): Array<Product & StoreProductMetadata> {
  return products.map(getStoreProduct);
}

export function getProductBySlug(slug: string) {
  return products.find((product) => product.slug === slug);
}





